/* React Plumber type roles: one class per role, each sets the whole bundle */
@utility type-display-large {
  font-size: var(--text-display-large);
  line-height: var(--text-display-large--line-height);
  letter-spacing: var(--text-display-large--letter-spacing);
  font-weight: var(--text-display-large--font-weight);
}
@utility type-headline-small {
  font-size: var(--text-headline-small);
  line-height: var(--text-headline-small--line-height);
  letter-spacing: var(--text-headline-small--letter-spacing);
  font-weight: var(--text-headline-small--font-weight);
}
@utility type-title-large {
  font-size: var(--text-title-large);
  line-height: var(--text-title-large--line-height);
  letter-spacing: var(--text-title-large--letter-spacing);
  font-weight: var(--text-title-large--font-weight);
}
@utility type-title-medium {
  font-size: var(--text-title-medium);
  line-height: var(--text-title-medium--line-height);
  letter-spacing: var(--text-title-medium--letter-spacing);
  font-weight: var(--text-title-medium--font-weight);
}
@utility type-body-large {
  font-size: var(--text-body-large);
  line-height: var(--text-body-large--line-height);
  letter-spacing: var(--text-body-large--letter-spacing);
  font-weight: var(--text-body-large--font-weight);
}
@utility type-body-large-compact {
  font-size: var(--text-body-large);
  line-height: var(--text-body-large-compact--line-height);
  letter-spacing: var(--text-body-large--letter-spacing);
  font-weight: var(--text-body-large--font-weight);
}
@utility type-body-small {
  font-size: var(--text-body-small);
  line-height: var(--text-body-small--line-height);
  letter-spacing: var(--text-body-small--letter-spacing);
  font-weight: var(--text-body-small--font-weight);
}
@utility type-label-medium {
  font-size: var(--text-label-medium);
  line-height: var(--text-label-medium--line-height);
  letter-spacing: var(--text-label-medium--letter-spacing);
  font-weight: var(--text-label-medium--font-weight);
  text-transform: uppercase;
}
@utility type-label-small {
  font-size: var(--text-label-small);
  line-height: var(--text-label-small--line-height);
  letter-spacing: var(--text-label-small--letter-spacing);
  font-weight: var(--text-label-small--font-weight);
  text-transform: uppercase;
}
